def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    # Each diagonal pair defines a ray continuing in that same direction.
    rays = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    rays.add((nr, nc, dr, dc, color))
    for r, c, dr, dc, color in rays:
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == background:
            out[rr][cc] = color
            rr += dr
            cc += dc
    return out

